// src/hooks/UseExceptions.js
import { useEffect, useState } from 'react';
import {
  addExceptionRule,
  deleteExceptionRule,
  fetchExceptionRules,
} from '../api/SettingApi';

const STORAGE_KEY = 'watchservice.exceptions';

function safeParseJson(raw) {
  try {
    const v = JSON.parse(raw);
    return v;
  } catch {
    return null;
  }
}

function normalizeExceptions(list) {
  if (!Array.isArray(list)) return [];
  return list
    .filter(Boolean)
    .map((ex) => ({
      id: ex.id,
      type: ex.type || 'PATH',
      pattern: ex.pattern || '',
      memo: ex.memo || '',
    }))
    .filter((ex) => ex.pattern);
}

export function useExceptions() {
  const [exceptions, setExceptions] = useState(() => {
    const raw = localStorage.getItem(STORAGE_KEY);
    const parsed = raw ? safeParseJson(raw) : null;
    return Array.isArray(parsed) ? normalizeExceptions(parsed) : [];
  });

  const [backendAvailable, setBackendAvailable] = useState(false);

  useEffect(() => {
    let mounted = true;

    (async () => {
      try {
        const list = await fetchExceptionRules();
        const next = normalizeExceptions(list);
        if (!mounted) return;

        setExceptions(next);
        setBackendAvailable(true);
        localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
      } catch (e) {
        setBackendAvailable(false);
      }
    })();

    return () => {
      mounted = false;
    };
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(exceptions));
    } catch {
      // ignore
    }
  }, [exceptions]);

  const addException = async (type, pattern, memo = '') => {
    const t = String(type || 'PATH').trim();
    const p = String(pattern || '').trim();
    const m = String(memo || '').trim();
    if (!p) return;

    // 중복 방지
    if (exceptions.some((ex) => ex.type === t && ex.pattern === p)) return;

    if (backendAvailable) {
      try {
        const created = await addExceptionRule({ type: t, pattern: p, memo: m });
        const normalized = normalizeExceptions([created])[0];
        if (normalized) {
          setExceptions((prev) => [...prev, normalized]);
          return;
        }
      } catch (e) {
        // server fail -> local fallback
      }
    }

    setExceptions((prev) => {
      const nextId = prev.length === 0 ? 1 : Math.max(...prev.map((x) => Number(x.id) || 0)) + 1;
      return [...prev, { id: nextId, type: t, pattern: p, memo: m }];
    });
  };

  const removeException = async (id) => {
    const targetId = id;

    if (backendAvailable) {
      try {
        await deleteExceptionRule(targetId);
        setExceptions((prev) => prev.filter((ex) => ex.id !== targetId));
        return;
      } catch (e) {
        // server fail -> local fallback
      }
    }

    setExceptions((prev) => prev.filter((ex) => ex.id !== targetId));
  };

  return {
    exceptions,
    setExceptions,
    addException,
    removeException,
    backendAvailable,
  };
}
